    """Implement a function that takes an non-negative integer and returns an array of some first n
    integers that are prime numbers and less than n.
    """
    def is_prime(x):
        if x < 2:
            return False
        if x == 2:
            return True
        if x % 2 == 0:
            return False
        for i in range(3, int(x**0.5) + 1, 2):
            if x % i == 0:
                return False
        return True

    return [x for x in range(2, n) if is_prime(x)]
