def count_up_to(n):
    if n < 2:
        return []
    def is_prime(x):
        if x < 2: return False
        if x == 2: return True
        if x % 2 == 0: return False
        for i in range(3, int(x**0.5) + 1, 2):
            if x % i == 0: return False
        return True
    result = []
    for i in range(2, n):
        if is_prime(i):
            result.append(i)
            if len(result) == n:
                break
    return result
```

