        if x % 2 == 0 or x % 3 == 0:
            return False
        i = 5
        while i * i <= x:
            if x % i == 0 or x % (i + 2) == 0:
                return False
            i += 6
        return True

    result = []
    for x in range(2, n):
        if is_prime(x):
            result.append(x)
        if len(result) == n:
            break
    return result
